{
  "story": "Merge sort divides the array into single elements, then merges sorted pairs recursively until the entire collection is fully ordered.",
  "aha": {
    "stateId": "merge",
    "observation": "Sub-arrays combine into a sorted sequence by comparing leading items."
  },
  "layout": {
    "preset": "stepper-states",
    "width": 640
  },
  "parts": [
    {
      "id": "rail",
      "kind": "step-rail",
      "bind": {
        "active": "inputs.stepIndex",
        "items": "variant.states"
      }
    },
    {
      "id": "picture",
      "kind": "fixed-picture",
      "bind": {
        "active": "inputs.stepIndex",
        "regions": "variant.regions",
        "reason": "variant.states.why"
      }
    },
    {
      "id": "callout",
      "kind": "active-callout",
      "bind": {
        "reason": "variant.states.why",
        "target": "variant.states.calloutRegion",
        "text": "variant.states.sentence"
      }
    },
    {
      "id": "readout",
      "kind": "value-readout",
      "bind": {
        "values": "variant.states.readouts"
      }
    }
  ],
  "controls": [
    {
      "id": "stepIndex",
      "kind": "index",
      "label": "Step",
      "options": [
        "divide",
        "split",
        "merge",
        "sorted"
      ]
    }
  ],
  "data": {
    "variants": [
      {
        "label": "Merge Sort",
        "regions": [
          {
            "id": "r1",
            "label": "Left Partition",
            "kind": "array",
            "values": ["3", "1"]
          },
          {
            "id": "r2",
            "label": "Right Partition",
            "kind": "array",
            "values": ["4", "2"]
          },
          {
            "id": "r3",
            "label": "Output Buffer",
            "kind": "array",
            "values": ["1", "2", "3", "4"]
          }
        ],
        "states": [
          {
            "id": "divide",
            "label": "Initial",
            "short": "Start",
            "sentence": "Unsorted array loaded.",
            "why": "Begin with four items.",
            "active": ["r1", "r2"],
            "calloutRegion": "r1",
            "readouts": [
              {
                "id": "depth",
                "label": "Recursion Depth",
                "value": "0"
              }
            ]
          },
          {
            "id": "split",
            "label": "Split",
            "short": "Split",
            "sentence": "Array split into halves.",
            "why": "Halving reduces problem size.",
            "active": ["r1", "r2"],
            "calloutRegion": "r2",
            "readouts": [
              {
                "id": "depth",
                "label": "Recursion Depth",
                "value": "1"
              }
            ]
          },
          {
            "id": "merge",
            "label": "Merge",
            "short": "Merge",
            "sentence": "Comparing smallest elements.",
            "why": "Order is established during merge.",
            "active": ["r3"],
            "calloutRegion": "r3",
            "readouts": [
              {
                "id": "depth",
                "label": "Recursion Depth",
                "value": "2"
              }
            ]
          },
          {
            "id": "sorted",
            "label": "Complete",
            "short": "Done",
            "sentence": "Collection is fully sorted.",
            "why": "Merge completes all invariants.",
            "active": ["r3"],
            "calloutRegion": "r3",
            "readouts": [
              {
                "id": "depth",
                "label": "Recursion Depth",
                "value": "0"
              }
            ]
          }
        ]
      }
    ]
  }
}
